import unittest
from app import quote

class QuoteTest(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(quote(3), 100)
    def test_boundary(self):
        for weight, expected in ((1, 100), (5, 100), (6, 200)):
            with self.subTest(weight=weight):
                self.assertEqual(quote(weight), expected)
    def test_express(self):
        for weight, expected in ((5, 150), (6, 250)):
            with self.subTest(weight=weight):
                self.assertEqual(quote(weight, True), expected)
    def test_invalid(self):
        for weight in (0, -1):
            for express in (False, True):
                with self.subTest(weight=weight, express=express):
                    with self.assertRaises(ValueError):
                        quote(weight, express)

